from pathlib import Path
import hashlib,json,re,shlex,subprocess
s=Path('.tmp/pr-size-owner')
expected=json.loads((s/'expectations.json').read_text())
fixture_hashes=json.loads((s/'fixture-files.json').read_text())
verdicts=[]
replayed=[]
for arm in [1,2]:
    d=s/f'trials/run-{arm}'
    result=json.loads((d/'result.json').read_text())
    entries={}
    for item in result['cases']:
        if 'layers' in item:
            for layer in item['layers']:
                entries[item['id']+'.'+layer['id']]=layer
        else:
            entries[item['id']]=item
    assert set(entries)==set(expected)
    seen=set()
    for key,exp in expected.items():
        got=entries[key]
        assert got['verdict']==exp['verdict'] and got['changed_lines']==exp['total'],(arm,key)
        if exp['total'] is not None:
            for field in ['additions','deletions']:
                assert got[field]==exp[field],(arm,key,field)
            assert got['selected_base_sha']==exp['base'] and got['selected_head_sha']==exp['head']
            assert got['cap']==(600 if key=='standalone-check' else 5000)
        if 'binary' in exp:
            assert got['binary_paths']==exp['binary'] and got['binary_review_burden']
        gate=got.get('publication_size_gate_passed',got.get('size_gate_permits_publication'))
        assert gate==(exp['verdict']=='within-cap'),(arm,key)
        evidence=got.get('evidence',got.get('deciding_git_evidence'))
        assert evidence
        for record in evidence:
            args=record['command'] if isinstance(record['command'],list) else shlex.split(record['command'])
            assert args[0]=='git' and '--git-dir=fixture.git' in args
            flags={'--no-pager','--git-dir=fixture.git','--verify','--no-ext-diff','--no-textconv','--shortstat','--numstat','--'}
            operations={'diff','rev-parse','merge-base'}
            for arg in args[1:]:
                assert arg in flags or arg in operations or re.fullmatch(r'[0-9a-f]{40}(?:\^\{commit\}|\.\.\.[0-9a-f]{40})?',arg),arg
            identity=tuple(args)
            if identity in seen:
                continue
            seen.add(identity)
            run=subprocess.run(args,cwd=d,capture_output=True,text=True)
            assert run.returncode==record['exit_code'],(arm,key,args)
            if 'stdout' in record:
                assert run.stdout==record['stdout'] and run.stderr==record['stderr'],(arm,key,args)
            else:
                assert (run.stdout+run.stderr).strip()==record['output'].strip(),(arm,key,args)
            replayed.append({'arm':arm,'case':key,'command':args,'exitCode':run.returncode,'stdout':run.stdout,'stderr':run.stderr})
        verdicts.append({'arm':arm,'case':key,'result':'pass','count':got['changed_lines'],'verdict':got['verdict']})
    entrypoints=result.get('skill_entrypoints',result.get('skill_entrypoint_sha256'))
    for entry in entrypoints:
        assert hashlib.sha256((d/entry['path']).read_bytes()).hexdigest()==entry['sha256']
    actual={str(p.relative_to(d/'fixture.git')):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted((d/'fixture.git').rglob('*')) if p.is_file()}
    assert actual==fixture_hashes,(arm,'fixture mutated')
    for name in ['request.md','cases.json','catalog.json']:
        assert (s/'trials/run-1'/name).read_bytes()==(s/'trials/run-2'/name).read_bytes()
(s/'observed-verdicts.json').write_text(json.dumps(verdicts,indent=2)+'\n')
(s/'replayed-git-evidence.json').write_text(json.dumps(replayed,indent=2)+'\n')
for item in verdicts:
    print(f"run-{item['arm']} {item['case']}: PASS, count={item['count']}, {item['verdict']}")
print(f'Replayed {len(replayed)} reported read-only Git observations; exact results and unchanged fixture verified.')
